443	     * @param owner the persisted owner to represent
444	     * @return the owner DTO with its derived read-only fields populated
445	     */
446	    private OwnerDto toOwnerDtoWithDerivedFields(Owner owner) {
447	        owner.setHouseholdSize(householdSize(owner));
448	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
449	        int membershipLevel = membershipLevel(owner);
450	        ownerDto.setMembershipLevel(membershipLevel);
451	        ownerDto.setOwnerSegment(ownerMapper.ownerSegment(owner, membershipLevel));
452	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
453	        ownerDto.setCapacityWarning(capacityWarning(owner.getCity()));
454	        ownerDto.setIdentityKey(identityKey(owner));
455	        Integer possibleDuplicateOf = owner.getPossibleDuplicateOf();
456	        ownerDto.setPossibleDuplicate(possibleDuplicateOf != null);
457	        ownerDto.setPossibleDuplicateOf(possibleDuplicateOf);
458	        return ownerDto;
459	    }
