608	    /**
609	     * Validates the owner's optional {@code postcode} against its {@code city} region. Postcode is
610	     * validated only when present, so an owner created without one is accepted unchanged. A supplied
611	     * postcode is already constrained to four digits by Bean Validation on {@link OwnerFieldsDto}; this
612	     * additionally rejects a well-formed postcode that is out of range for the city's region using the
613	     * shared {@link Region#acceptsPostcode(int) region-to-postcode} table ({@code NSW 2000-2099},
614	     * {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known region accepts any 4-digit
615	     * postcode. An out-of-range postcode is reported through an {@link InvalidOwnerPostcodeException},
616	     * which the {@code ExceptionControllerAdvice} renders as a 400 response.
617	     *
618	     * @param city the city of the owner being created
619	     * @param postcode the supplied postcode, or {@code null} when omitted
620	     * @throws InvalidOwnerPostcodeException if the postcode is out of range for the city's region
621	     */
622	    private void rejectInvalidPostcode(String city, String postcode) {
623	        if (postcode == null || postcode.isBlank()) {
624	            return;
625	        }
626	        Region.forCity(city).ifPresent(region -> {
627	            if (!region.acceptsPostcode(Integer.parseInt(postcode))) {
628	                throw new InvalidOwnerPostcodeException(postcode, city);
629	            }
630	        });
631	    }
632	
633	    /**
634	     * Number of leading hex characters of the identity hash retained as the {@code HASH8} segment of
635	     * the {@code memberId}.
636	     */
637	    private static final int MEMBER_ID_HASH_LENGTH = 8;
638	
639	    /**
640	     * Builds the unified {@code memberId} assigned to a newly created owner, formatted
641	     * {@code '<REGION><FY><HASH8><CHK>'}: {@code REGION} is the owner's canonical region code resolved
642	     * from its {@code postcode} (falling back to its {@code city}) through the shared
643	     * {@link Region#code(String, String)}; {@code FY} is the two-digit fiscal year of the owner's
644	     * (business-day-adjusted) {@code registrationDate} ({@link OwnerMapper#fiscalYearSegment(Owner)});
645	     * {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest of the owner's
646	     * normalized telephone followed by its last name; and {@code CHK} is a single Luhn check digit over
647	     * the digits of {@code '<REGION><FY><HASH8>'} (e.g. {@code 'NSW261A2B3C4D5'}). When this base id
648	     * collides with an existing owner's {@code memberId}, {@code '-<n>'} is appended with the smallest
649	     * {@code n} of 2 or more that makes the result unique (e.g. {@code 'NSW261A2B3C4D5-2'}), so distinct
650	     * owners always receive distinct member ids.
651	     *
652	     * @param owner the owner being created, with its telephone already normalized and its registration
653	     *              date set
654	     * @return the formatted, de-duplicated member id
655	     */
656	    private String memberId(Owner owner) {
657	        String region = Region.code(owner.getPostcode(), owner.getCity());
658	        String fiscalYear = ownerMapper.fiscalYearSegment(owner);
659	        String hash8 = sha256Hasher.hexPrefix(owner.getTelephone() + owner.getLastName(), MEMBER_ID_HASH_LENGTH);
660	        String core = region + fiscalYear + hash8;
661	        String base = core + Luhn.checkDigit(core);
662	        return deduplicate(base, Owner::getMemberId);
663	    }
664	
665	    /**
666	     * Ensures the given {@code base} identifier does not collide with an existing owner's identifier of
667	     * the same kind, read from each owner by {@code identifier}. When no existing owner carries the base
668	     * value it is returned unchanged; otherwise {@code '-<n>'} is appended with the smallest {@code n} of
669	     * 2 or more that yields a value held by no existing owner. Owners for which {@code identifier} yields
670	     * {@code null} are ignored (a {@code null} never collides). Written field-agnostically - like the
671	     * create endpoint's other owner scans ({@link #findExistingOwner(Function, String)},
672	     * {@link #countOwners(Predicate)}) - so the collision search lives in exactly one place and each
673	     * caller supplies only which identifier it de-duplicates.
674	     *
675	     * @param base the computed base identifier to make unique among existing owners
676	     * @param identifier reads the identifier of the same kind from an existing owner (may return {@code null})
677	     * @return the base value, or a {@code '<base>-<n>'} variant that is unique among existing owners
678	     */
679	    private String deduplicate(String base, Function<Owner, String> identifier) {
680	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
681	            .map(identifier)
682	            .filter(java.util.Objects::nonNull)
683	            .collect(java.util.stream.Collectors.toSet());
684	        if (!existing.contains(base)) {
685	            return base;
686	        }
687	        int n = 2;
688	        while (existing.contains(base + "-" + n)) {
689	            n++;
690	        }
691	        return base + "-" + n;
692	    }
693	
694	    /**
695	     * Counts how many existing owners already share the given {@code firstName} and {@code lastName},
696	     * compared case-insensitively (using {@link java.util.Locale#ROOT}-independent
697	     * {@link String#equalsIgnoreCase(String)}). The count reflects the owners present before the
698	     * current create, so a name that is unique on create yields {@code 0}. The value is stored on the
699	     * new owner and surfaced as the read-only {@code namesakeCount} field.
700	     *
701	     * @param firstName the first name of the owner being created
702	     * @param lastName the last name of the owner being created
703	     * @return the number of existing owners with the same first and last name (case-insensitive)
704	     */
705	    private int namesakeCount(String firstName, String lastName) {
706	        return (int) countOwners(owner -> equalsIgnoreCase(owner.getFirstName(), firstName)
707	            && equalsIgnoreCase(owner.getLastName(), lastName));
708	    }
709	
710	    private boolean equalsIgnoreCase(String a, String b) {
711	        return a == null ? b == null : a.equalsIgnoreCase(b);
712	    }
713	
714	    /**
715	     * The maximum number of owners a single city may contain. Once a city already holds this many
716	     * owners, further owners in that city are rejected by {@link #rejectCityAtCapacity(String)}.
717	     */
718	    private static final long MAX_OWNERS_PER_CITY = 50L;
719	
720	    /**
721	     * Rejects a create request whose city already contains {@link #MAX_OWNERS_PER_CITY} or more
722	     * owners. Existing owners are matched to the requested city case-insensitively (using
723	     * {@link java.util.Locale#ROOT}-independent {@link String#equalsIgnoreCase(String)}), mirroring
724	     * the per-city counting used for the member id. A city at capacity is reported through an
725	     * {@link OwnerCityAtCapacityException}, which the {@code ExceptionControllerAdvice} renders as a
726	     * 409 Conflict response.
727	     *
728	     * @param city the city of the owner being created
729	     * @throws OwnerCityAtCapacityException if the city already holds the maximum number of owners
730	     */
731	    private void rejectCityAtCapacity(String city) {
